mobile":"40px 16px"}},"layout":{"engine":"flex","flex":{"direction":"column","gap":"16px"}},"tag":"section","visual":{"bgColor":"#f8fafc"}},"children":[{"id":"contact-form-title","type":"core.heading","props":{"color":"#0f172a","tag":"h2","text":"在线留言","typography":{"desktop":{"fontSize":"28px","textAlign":"left"},"tablet":{},"mobile":{}}}},{"id":"contact-form-desc","type":"core.text","props":{"color":"#475569","mode":"plaintext","text":"填写下面的表单，我们会在一个工作日内与你联系。","typography":{"desktop":{"fontSize":"16px"},"tablet":{},"mobile":{}}}},{"id":"contact-form-node","type":"core.form","props":{"action":"/contact/submit","fields":[{"label":"您的称呼","name":"name","placeholder":"请输入姓名或称呼","required":true,"type":"text"},{"label":"联系邮箱","name":"email","placeholder":"name@example.com","required":true,"type":"email"},{"label":"咨询类型","name":"topic","options":["产品咨询","合作洽谈","售后支持","其他"],"type":"select"},{"label":"留言内容","name":"message","placeholder":"请描述您的需求或问题","required":true,"type":"textarea"},{"label":"同意隐私政策","name":"consent","required":true,"type":"checkbox"}],"method":"post","submitLabel":"提交留言"}}]},{"id":"contact-map","type":"core.container","props":{"box":{"padding":{"desktop":"64px 24px","mobile":"40px 16px"}},"layout":{"engine":"flex","flex":{"direction":"column","gap":"16px"}},"tag":"section","visual":{}},"children":[{"id":"contact-map-title","type":"core.heading","props":{"color":"#0f172a","tag":"h2","text":"到访路线","typography":{"desktop":{"fontSize":"28px","textAlign":"left"},"tablet":{},"mobile":{}}}},{"id":"contact-map-list","type":"core.list","props":{"items":[{"icon":"check","text":"地铁：乘坐 2 号线至示例站，从 B 口步行 300 米。"},{"icon":"check","text":"公交：乘坐 15 路 / 37 路至示例大厦站下车。"},{"icon":"check","text":"驾车：园区地下停车场，首小时免费。"}],"style":"icon"}},{"id":"contact-map-image","type":"core.image","props":{"alt":"办公地点示意","aspectRatio":"21:9","borderRadius":"12px","maxWidth":"1000px","objectFit":"cover","src":"https://placehold.co/1200x600/png","width":"100%"}}]}]}'::jsonb, 1, now(), now()),
    ('3f1b6a52-7c4d-4a01-9e10-11f0a6b2c305', '展示页 · 政策条款', 'page',
     '{"settings":{"layout":{"mode":"boxed","maxWidth":"1200px"},"seo":{"title":"政策条款","description":"服务条款、隐私政策与内容规范。","schemaType":"website"}},"root":[{"id":"policy-head","type":"core.container","props":{"box":{"padding":{"desktop":"72px 24px","mobile":"48px 16px"}},"layout":{"engine":"flex","flex":{"direction":"column","gap":"16px"}},"tag":"section","visual":{"bgColor":"#0f172a"}},"children":[{"id":"policy-head-title","type":"core.heading","props":{"color":"#ffffff","tag":"h1","text":"政策条款","typography":{"desktop":{"fontSize":"40px","textAlign":"center"},"tablet":{"fontSize":"40px","textAlign":"center"},"mobile":{"fontSize":"40px","textAlign":"center"}}}},{"id":"policy-head-desc","type":"core.text","props":{"color":"#cbd5e1","mode":"plaintext","text":"最近更新：2026-01-01 · 生效日期：2026-01-01","typography":{"desktop":{"fontSize":"14px","textAlign":"center"},"tablet":{"fontSize":"14px","textAlign":"center"},"mobile":{"fontSize":"14px","textAlign":"center"}}}}]},{"id":"policy-toc","type":"core.container","props":{"box":{"padding":{"desktop":"48px 24px","mobile":"32px 16px"}},"layout":{"engine":"flex","flex":{"direction":"column","gap":"16px"}},"tag":"section","visual":{"bgColor":"#f8fafc"}},"children":[{"id":"policy-toc-title","type":"core.heading","props":{"color":"#0f172a","tag":"h2","text":"条款目录","typography":{"desktop":{"fontSize":"24px","textAlign":"left"},"tablet":{},"mobile":{}}}},{"id":"policy-toc-list","type":"core.list","props":{"items":[{"icon":"check","text":"一、服务说明"},{"icon":"check","text":"二、账号与使用规范"},{"icon":"check","text":"三、隐私与数据保护"},{"icon":"check","text":"四、内容规范"},{"icon":"check","text":"五、免责声明"},{"icon":"check","text":"六、条款变更"}],"style":"icon"}}]},{"id":"policy-body","type":"core.container","props":{"box":{"padding":{"desktop":"48px 24px","mobile":"32px 16px"}},"layout":{"engine":"flex","flex":{"direction":"column","gap":"16px"}},"tag":"section","visual":{}},"children":[{"id":"policy-s1","type":"core.heading","props":{"color":"#0f172a","tag":"h2","text":"一、服务说明","typography":{"desktop":{"fontSize":"24px","textAlign":"left"},"tablet":{},"mobile":{}}}},{"id":"policy-s1-p","type":"core.text","props":{"color":"#334155","mode":"plaintext","text":"本条款适用于你使用本平台提供的建站、内容管理与发布服务。使用本服务即表示你已阅读并同意本条款。","typography":{"desktop":{"fontSize":"16px"},"tablet":{},"mobile":{}}}},{"id":"policy-d1","type":"core.divider","props":{}},{"id":"policy-s2","type":"core.heading","props":{"color":"#0f172a","tag":"h2","text":"二、账号与使用规范","typography":{"desktop":{"fontSize":"24px","textAlign":"left"},"tablet":{},"mobile":{}}}},{"id":"policy-s2-p","type":"core.text","props":{"color":"#334155","mode":"plaintext","text":"你应对账号下的全部操作负责，不得将账号转借他人。禁止利用本服务发布违法、侵权或误导性内容，不得进行任何影响服务稳定性的行为。","typography":{"desktop":{"fontSize":"16px"},"tablet":{},"mobile":{}}}},{"id":"policy-d2","type":"core.divider","props":{}},{"id":"policy-s3","type":"core.heading","props":{"color":"#0f172a","tag":"h2","text":"三、隐私与数据保护","typography":{"desktop":{"fontSize":"24px","textAlign":"left"},"tablet":{},"mobile":{}}}},{"id":"policy-s3-p","type":"core.text","props":{"color":"#334155","mode":"plaintext","text":"我们仅收集提供服务所必需的信息，访问统计使用匿名化的派生标识，不用于识别自然人。未经你的同意，我们不会向第三方出售你的数据。","typography":{"desktop":{"fontSize":"16px"},"tablet":{},"mobile":{}}}},{"id":"policy-d3","type":"core.divider","props":{}},{"id":"policy-s4","type":"core.heading","props":{"color":"#0f172a","tag":"h2","text":"四、内容规范","typography":{"desktop":{"fontSize":"24px","textAlign":"left"},"tablet":{},"mobile":{}}}},{"id":"policy-s4-p","type":"core.text","props":{"color":"#334155","mode":"plaintext","text":"你对自己上传的文字、图片与视频拥有全部权利，并保证不侵犯任何第三方权益。我们有权对明显违规的内容进行下架处理。","typography":{"desktop":{"fontSize":"16px"},"tablet":{},"mobile":{}}}},{"id":"policy-d4","type":"core.divider","props":{}},{"id":"policy-s5","type":"core.heading","props":{"color":"#0f172a","tag":"h2","text":"五、免责声明","typography":{"desktop":{"fontSize":"24px","textAlign":"left"},"tablet":{},"mobile":{}}}},{"id":"policy-s5-p","type":"core.text","props":{"color":"#334155","mode":"plaintext","text":"因不可抗力、第三方服务中断或你自身配置错误导致的服务不可用，我们不承担由此产生的间接损失。建议在发布前使用预览功能核对效果。","typography":{"desktop":{"fontSize":"16px"},"tablet":{},"mobile":{}}}},{"id":"policy-d5","type":"core.divider","props":{}},{"id":"policy-s6","type":"core.heading","props":{"color":"#0f172a","tag":"h2","text":"六、条款变更","typography":{"desktop":{"fontSize":"24px","textAlign":"left"},"tablet":{},"mobile":{}}}},{"id":"policy-s6-p","type":"core.text","props":{"color":"#334155","mode":"plaintext","text":"条款如需变更，我们会在本页面更新并标注生效日期。继续使用服务即视为接受变更后的条款。","typography":{"desktop":{"fontSize":"16px"},"tablet":{},"mobile":{}}}}]},{"id":"policy-contact","type":"core.container","props":{"box":{"padding":{"desktop":"56px 24px","mobile":"40px 16px"}},"layout":{"engine":"flex","flex":{"direction":"column","gap":"16px"}},"tag":"section","visual":{"bgColor":"#f8fafc"}},"children":[{"id":"policy-contact-title","type":"core.heading","props":{"color":"#0f172a","tag":"h2","text":"对条款有疑问？","typography":{"desktop":{"fontSize":"24px","textAlign":"center"},"tablet":{"fontSize":"24px","textAlign":"center"},"mobile":{"fontSize":"24px","textAlign":"center"}}}},{"id":"policy-contact-desc","type":"core.text","props":{"color":"#475569","mode":"plaintext","text":"欢迎通过邮件或留言表单与我们沟通。","typography":{"desktop":{"fontSize":"16px","textAlign":"center"},"tablet":{"fontSize":"16px","textAlign":"center"},"mobile":{"fontSize":"16px","textAlign":"center"}}}},{"id":"policy-contact-actions","type":"core.container","props":{"box":{"padding":{"desktop":"8px 0 0","mobile":"8px 0 0"}},"layout":{"engine":"grid","grid":{"columnGap":"16px","columns":{"desktop":1,"mobile":1,"tablet":1},"rowGap":"16px"}},"tag":"div"},"children":[{"id":"policy-contact-btn","type":"core.button","props":{"action":"internal","bg":"#2563eb","size":"lg","text":"联系我们","textColor":"#ffffff","value":"/contact"}}]}]}]}'::jsonb, 1, now(), now()),
    ('3f1b6a52-7c4d-4a01-9e10-11f0a6b2c306', '展示页 · 常见问题', 'page',
     '{"settings":{"layout":{"mode":"boxed","maxWidth":"1000px"},"seo":{"title":"常见问题","description":"关于账号、内容、发布与计费的常见问题解答。","schemaType":"faq"}},"root":[{"id":"faq-head","type":"core.container","props":{"box":{"padding":{"desktop":"72px 24px","mobile":"48px 16px"}},"layout":{"engine":"flex","flex":{"direction":"column","gap":"16px"}},"tag":"section","visual":{"bgColor":"#0f172a"}},"children":[{"id":"faq-head-title","type":"core.heading","props":{"color":"#ffffff","tag":"h1","text":"常见问题","typography":{"desktop":{"fontSize":"40px","textAlign":"center"},"tablet":{"fontSize":"40px","textAlign":"center"},"mobile":{"fontSize":"40px","textAlign":"center"}}}},{"id":"faq-head-desc","type":"core.text","props":{"color":"#cbd5e1","mode":"plaintext","text":"先看看这里有没有你要的答案。","typography":{"desktop":{"fontSize":"16px","textAlign":"center"},"tablet":{"fontSize":"16px","textAlign":"center"},"mobile":{"fontSize":"16px","textAlign":"center"}}}}]},{"id":"faq-general","type":"core.container","props":{"box":{"padding":{"desktop":"56px 24px","mobile":"36px 16px"}},"layout":{"engine":"flex","flex":{"direction":"column","gap":"16px"}},"tag":"section","visual":{}},"children":[{"id":"faq-general-title","type":"core.heading","props":{"color":"#0f172a","tag":"h2","text":"账号与使用","typography":{"desktop":{"fontSize":"26px","textAlign":"left"},"tablet":{},"mobile":{}}}},{"id":"faq-general-list","type":"core.faq","props":{"items":[{"answer":"\u003cp\u003e进入控制台后点击「新建站点」，填写站点名称与默认语言即可。系统会自动准备一套默认主题与首页蓝图，你可以在画布上直接修改。\u003c/p\u003e","open":true,"question":"如何创建一个新站点？"},{"answer":"\u003cp\u003e在登录页点击「忘记密码」，通过注册邮箱重置。若邮箱已不可用，请联系管理员在后台重置密码。\u003c/p\u003e","question":"忘记密码怎么办？"},{"answer":"\u003cp\u003e可以。在「管理员与角色」中创建账号并分配角色，权限按接口粒度控制，可以只给内容编辑权限而不给发布权限。\u003c/p\u003e","question":"可以邀请团队成员协作吗？"}]}}]},{"id":"faq-content","type":"core.container","props":{"box":{"padding":{"desktop":"56px 24px","mobile":"36px 16px"}},"layout":{"engine":"flex","flex":{"direction":"column","gap":"16px"}},"tag":"section","visual":{"bgColor":"#f8fafc"}},"children":[{"id":"faq-content-title","type":"core.heading","props":{"color":"#0f172a","tag":"h2","text":"内容与页面","typography":{"desktop":{"fontSize":"26px","textAlign":"left"},"tablet":{},"mobile":{}}}},{"id":"faq-content-list","type":"core.faq","props":{"items":[{"answer":"\u003cp\u003e蓝图只用于初始化页面文档，复制完成后就与蓝图再无关系；内容结构模板每次构建都会参与，改动会传播到使用它的实例。\u003c/p\u003e","open":true,"question":"蓝图和模板有什么区别？"},{"answer":"\u003cp\u003e多数情况下不需要。发布时会重新构建产物；如果只改了主题或组件版本，系统会把相关页面标记为待重建。\u003c/p\u003e","question":"页面改动后需要手动重建吗？"},{"answer":"\u003cp\u003e可以。先在站点设置里启用语言，再为每种语言维护对应的译文，发布时会为每种语言生成独立的静态产物。\u003c/p\u003e","question":"可以给页面做多语言吗？"},{"answer":"\u003cp\u003e支持。正文编辑器保留了标题层级、表格、折叠块与水平线，服务端会按白名单清洗后输出。\u003c/p\u003e","question":"文章正文支持表格和折叠块吗？"}]}}]},{"id":"faq-publish","type":"core.container","props":{"box":{"padding":{"desktop":"56px 24px","mobile":"36px 16px"}},"layout":{"engine":"flex","flex":{"direction":"column","gap":"16px"}},"tag":"section","visual":{}},"children":[{"id":"faq-publish-title","type":"core.heading","props":{"color":"#0f172a","tag":"h2","text":"发布与访问","typography":{"desktop":{"fontSize":"26px","textAlign":"left"},"tablet":{},"mobile":{}}}},{"id":"faq-publish-list","type":"core.faq","props":{"items":[{"answer":"\u003cp\u003e构建通常在数秒内完成，完成后访问路径立即指向新的静态产物。\u003c/p\u003e","open":true,"question":"发布后多久生效？"},{"answer":"\u003cp\u003e可以。每次发布都会保留不可变的产物版本，在发布记录里选择任一版本即可回滚。\u003c/p\u003e","question":"发布错了可以回滚吗？"},{"answer":"\u003cp\u003e不会。访客访问的是已经激活的静态文件，渲染与数据查询都发生在发布阶段。\u003c/p\u003e","question":"访客访问会查询数据库吗？"}]}}]},{"id":"faq-billing","type":"core.container","props":{"box":{"padding":{"desktop":"56px 24px","mobile":"36px 16px"}},"layout":{"engine":"flex","flex":{"direction":"column","gap":"16px"}},"tag":"section","visual":{"bgColor":"#f8fafc"}},"children":[{"id":"faq-billing-title","type":"core.heading","props":{"color":"#0f172a","tag":"h2","text":"计费与支持","typography":{"desktop":{"fontSize":"26px","textAlign":"left"},"tablet":{},"mobile":{}}}},{"id":"faq-billing-list","type":"core.faq","props":{"items":[{"answer":"\u003cp\u003e按超出部分的实际访问量结算，账单在次月生成，可在控制台查看明细。\u003c/p\u003e","open":true,"question":"超出套餐的访问量怎么计费？"},{"answer":"\u003cp\u003e提供工单与邮件支持，工作时间内响应；企业版可约定专属响应时间。\u003c/p\u003e","question":"有技术支持吗？"}]}}]},{"id":"faq-cta","type":"core.container","props":{"box":{"padding":{"desktop":"56px 24px","mobile":"40px 16px"}},"layout":{"engine":"flex","flex":{"direction":"column","gap":"16px"}},"tag":"section","visual":{"bgColor":"#0f172a"}},"children":[{"id":"faq-cta-title","type":"core.heading","props":{"color":"#ffffff","tag":"h2","text":"没有找到答案？","typography":{"desktop":{"fontSize":"28px","textAlign":"center"},"tablet":{"fontSize":"28px","textAlign":"center"},"mobile":{"fontSize":"28px","textAlign":"center"}}}},{"id":"faq-cta-desc","type":"core.text","props":{"color":"#cbd5e1","mode":"plaintext","text":"把你的问题发给我们，我们会尽快回复。","typography":{"desktop":{"fontSize":"16px","textAlign":"center"},"tablet":{"fontSize":"16px","textAlign":"center"},"mobile":{"fontSize":"16px","textAlign":"center"}}}},{"id":"faq-cta-actions","type":"core.container","props":{"box":{"padding":{"desktop":"8px 0 0","mobile":"8px 0 0"}},"layout":{"engine":"grid","grid":{"columnGap":"16px","columns":{"desktop":1,"mobile":1,"tablet":1},"rowGap":"16px"}},"tag":"div"},"children":[{"id":"faq-cta-btn","type":"core.button","props":{"action":"internal","bg":"#2563eb","size":"lg","text":"提交问题","textColor":"#ffffff","value":"/contact"}}]}]}]}'::jsonb, 1, now(), now());

